import{_ as s,l as i,o as e,c as n,v as t,p as l,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"DHCP 与 NAT","description":"","frontmatter":{"title":"DHCP 与 NAT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dhcp-nat.md","filePath":"cs/dhcp-nat.md","lastUpdated":1789023840000}'),P={name:"cs/dhcp-nat.md"};function A(T,a,h,C,D,N){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="dhcp-与-nat" tabindex="-1">DHCP 与 NAT <a class="header-anchor" href="#dhcp-与-nat" aria-label="Permalink to &quot;DHCP 与 NAT&quot;">​</a></h1><div class="epigraph"><p>DHCP 把地址与默认路由租给主机；NAT 让私网多台主机复用少量公网地址，改写 IP 与端口。</p><footer>—— 据 RFC 2131, Dynamic Host Configuration Protocol；RFC 3022, Traditional IP Network Address Translator 整理</footer></div><p><a href="/cs/icmp">上一课</a>假定主机已有地址。<a href="/cs/icmp">IP 编址</a>要每接口一个 IP；手工配置不能规模化，IPv4 公网地址也不够每人一台。缺口是两件配套：<strong>DHCP 租约</strong>与 <strong>NAT 复用</strong>。本课不把 IPv6 地址空间当已解决。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主机启动时还没有 IP，不能先打开一个「配置 TCP」。DHCP：发现、提供、请求、确认，在 UDP 广播/中继上完成，交出地址、掩码、网关、DNS（DNS 课再用）。NAT：边界路由器改写私网源地址为公网，用端口区分会话，回包再改回。缺口不是 LPM 公式，而是地址的<strong>获得与改写</strong>。</p><p>本课不把 CGNAT 的全部端口耗尽策略写完。</p><p><span class="marginnote">私网段 RFC 1918：<code>10/8</code>、<code>172.16/12</code>、<code>192.168/16</code>。NAT 破坏「每个地址全球可达」，与端到端论证紧张：新会话难从外向内建。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>DHCP 客户端在 UDP 68，服务器 67；租约到期续租。NAT 表：(协议, 私网 IP, 端口) ↔ (公网 IP, 端口)，对 TCP/UDP 有状态；ICMP 用查询 ID 等。TTL 与校验和随改写重算。ALG 曾修补 FTP 等嵌地址的协议，脆弱，主干不依赖。</p>',9)),(e(),l(p,null,{default:r(()=>[c(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOST%5B%22%E6%97%A0%E5%9C%B0%E5%9D%80%E4%B8%BB%E6%9C%BA%22%5D%20--%3E%20DHCP%5B%22DHCP%20%E7%A7%9F%E7%BA%A6%22%5D%0A%20%20PRIV%5B%22%E7%A7%81%E7%BD%91%E5%88%86%E7%BB%84%22%5D%20--%3E%20NAT%5B%22%E6%94%B9%E5%86%99%E5%9C%B0%E5%9D%80%E7%AB%AF%E5%8F%A3%22%5D%0A%20%20NAT%20--%3E%20WAN%5B%22%E5%85%AC%E7%BD%91%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>DHCP 填好<a href="/cs/ip-subnet">子网</a>课的配置，主机才能 ARP 网关。NAT 让 <a href="/cs/lpm">LPM</a> 在公网只看见少量前缀，却让传输层五元组在边界被改写——后课 TCP 必须容忍，或应用改用中继。端到端：NAT 是中间盒状态，不是 Saltzer 意义上的「端」。这是后课 QUIC 与 NAT 超时、以及 IPv6 推动的背景。</p><p>与<a href="/cs/process-image">进程</a>无关：改写发生在路由器，主机套接字仍绑定私网地址。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 DHCP 欺骗写成攻击教程。不引入 IPsec 穿越 NAT 的全部封装。IPv6 用 SLAAC/DHCPv6，对照下一课；不要把 NAT66 当 IPv6 的必经之路。</p><p>中继代理让服务器不在广播域内。NAT 对分片重组的依赖是实现地雷，主干假定不分片或先重组再改写。</p><p>租约续期失败则地址应停止使用；NAT 表项超时则内网会话静默断开。</p><p>后课默认：IPv4 常靠 DHCP 与 NAT 撑着。地址长度与邻居发现如何换一套，下一课 IPv6 对照。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DHCP（RFC 2131）租地址与网关；NAT（RFC 3022）复用公网地址。</li><li>NAT 改写五元组，削弱端到端可达。</li><li>IPv6 用更大地址空间对照，下一课。</li><li>出处：RFC 2131；RFC 3022；RFC 1918；Kurose and Ross。</li></ul>',10))])}const f=s(P,[["render",A]]);export{m as __pageData,f as default};
